package com.shieldsurf.browser;

import android.app.*;import android.os.*;import android.content.*;import android.graphics.Color;import android.graphics.drawable.GradientDrawable;import android.net.Uri;import android.view.*;import android.view.inputmethod.EditorInfo;import android.view.inputmethod.InputMethodManager;import android.webkit.*;import android.widget.*;import java.io.ByteArrayInputStream;import java.util.*;

public class MainActivity extends Activity {
 private final int bg=Color.rgb(16,24,32),panel=Color.rgb(27,39,50),accent=Color.rgb(54,214,181),fg=Color.rgb(239,245,247);
 private LinearLayout tabsBar,webHolder; private EditText address; private ProgressBar progress; private TextView shieldLine;
 private final ArrayList<Tab> tabs=new ArrayList<>(); private int active=-1,blocked=0;
 private boolean blocking=true,confirmRedirect=true; private String pendingUrl; private int pendingTab=-1;
 private final Set<String> domains=new HashSet<>(Arrays.asList("doubleclick.net","googlesyndication.com","googleadservices.com","adservice.google.com","adnxs.com","adsrvr.org","adform.net","taboola.com","outbrain.com","scorecardresearch.com","quantserve.com","criteo.com","casalemedia.com","pubmatic.com","openx.net","rubiconproject.com","advertising.com","adroll.com","hotjar.com","fullstory.com","mouseflow.com","analytics.tiktok.com","moatads.com","yieldmo.com","smartadserver.com","sharethrough.com","33across.com","bidswitch.net","media.net","mgid.com","popads.net","popcash.net","propellerads.com","hilltopads.net","exoclick.com","trafficjunky.net","juicyads.com","onclickalgo.com","clickadu.com","pushground.com","adskeeper.co.uk","push-house.net","adf.ly"));
 private class Tab { WebView web; String title="Tab baru",url="https://www.google.com/"; Tab(WebView w){web=w;} }
 @Override public void onCreate(Bundle b){super.onCreate(b);blocking=getPreferences(0).getBoolean("blocking",true);confirmRedirect=getPreferences(0).getBoolean("redirects",true);build();newTab("https://www.google.com/");}
 private int dp(int n){return (int)(n*getResources().getDisplayMetrics().density+.5f);} private GradientDrawable round(int c,int r){GradientDrawable d=new GradientDrawable();d.setColor(c);d.setCornerRadius(dp(r));return d;}
 private Button btn(String t,int size){Button b=new Button(this);b.setText(t);b.setTextColor(fg);b.setTextSize(size);b.setAllCaps(false);b.setBackgroundColor(Color.TRANSPARENT);return b;}
 private void build(){LinearLayout root=new LinearLayout(this);root.setOrientation(1);root.setBackgroundColor(bg);
  LinearLayout bar=new LinearLayout(this);bar.setGravity(Gravity.CENTER_VERTICAL);bar.setPadding(dp(8),dp(7),dp(5),dp(5));TextView logo=new TextView(this);logo.setText("◈");logo.setTextColor(accent);logo.setTextSize(25);bar.addView(logo,new LinearLayout.LayoutParams(dp(32),dp(44)));
  address=new EditText(this);address.setSingleLine(true);address.setTextSize(14);address.setTextColor(fg);address.setHintTextColor(0xffa5b6be);address.setHint("Cari atau masukkan alamat");address.setPadding(dp(12),0,dp(12),0);address.setBackground(round(panel,16));address.setImeOptions(EditorInfo.IME_ACTION_GO);bar.addView(address,new LinearLayout.LayoutParams(0,dp(44),1));Button menu=btn("⋮",22);bar.addView(menu,new LinearLayout.LayoutParams(dp(40),dp(44)));menu.setOnClickListener(v->showMenu());root.addView(bar);
  HorizontalScrollView hsv=new HorizontalScrollView(this);hsv.setHorizontalScrollBarEnabled(false);tabsBar=new LinearLayout(this);tabsBar.setPadding(dp(7),dp(2),dp(7),dp(5));hsv.addView(tabsBar);root.addView(hsv,new LinearLayout.LayoutParams(-1,dp(43)));
  progress=new ProgressBar(this,null,android.R.attr.progressBarStyleHorizontal);progress.setMax(100);progress.setProgressTintList(android.content.res.ColorStateList.valueOf(accent));progress.setVisibility(View.GONE);root.addView(progress,new LinearLayout.LayoutParams(-1,dp(3)));
  shieldLine=new TextView(this);shieldLine.setTextColor(accent);shieldLine.setTextSize(11);shieldLine.setPadding(dp(10),dp(3),dp(10),dp(3));root.addView(shieldLine);
  webHolder=new LinearLayout(this);webHolder.setOrientation(1);root.addView(webHolder,new LinearLayout.LayoutParams(-1,0,1));
  LinearLayout nav=new LinearLayout(this);nav.setGravity(Gravity.CENTER);nav.setBackgroundColor(panel);String[] labels={"‹","›","⌂","+","☆","↻"};for(String label:labels){Button b=btn(label,23);nav.addView(b,new LinearLayout.LayoutParams(0,dp(45),1));b.setOnClickListener(v->{Tab t=current();if(label.equals("+"))newTab("https://www.google.com/");else if(t!=null){switch(label){case "‹":if(t.web.canGoBack())t.web.goBack();break;case "›":if(t.web.canGoForward())t.web.goForward();break;case "⌂":t.web.loadUrl("https://www.google.com/");break;case "☆":bookmark();break;case "↻":t.web.reload();break;}}});}root.addView(nav);
  address.setOnEditorActionListener((v,a,e)->{if(a==EditorInfo.IME_ACTION_GO||(e!=null&&e.getKeyCode()==KeyEvent.KEYCODE_ENTER)){navigate(address.getText().toString());((InputMethodManager)getSystemService(INPUT_METHOD_SERVICE)).hideSoftInputFromWindow(address.getWindowToken(),0);address.clearFocus();return true;}return false;});setContentView(root);}
 private void newTab(String url){WebView w=new WebView(this);Tab t=new Tab(w);t.url=url;tabs.add(t);webHolder.addView(w,new LinearLayout.LayoutParams(-1,-1));w.setVisibility(View.GONE);configure(t);switchTab(tabs.size()-1);w.loadUrl(url);}
 private void configure(Tab t){WebView w=t.web;WebSettings s=w.getSettings();s.setJavaScriptEnabled(true);s.setDomStorageEnabled(true);s.setAllowFileAccess(false);s.setAllowContentAccess(false);s.setMixedContentMode(WebSettings.MIXED_CONTENT_NEVER_ALLOW);s.setSafeBrowsingEnabled(true);s.setSupportZoom(true);s.setBuiltInZoomControls(true);s.setDisplayZoomControls(false);
  w.setWebChromeClient(new WebChromeClient(){@Override public void onProgressChanged(WebView v,int p){if(current()==t){progress.setProgress(p);progress.setVisibility(p<100?View.VISIBLE:View.GONE);}}@Override public void onReceivedTitle(WebView v,String title){t.title=(title==null||title.trim().isEmpty())?host(t.url):title;drawTabs();}@Override public boolean onCreateWindow(WebView view,boolean dialog,boolean gesture,Message resultMsg){Toast.makeText(MainActivity.this,"Pop-up/jendela baru diblokir. Gunakan + untuk tab baru.",Toast.LENGTH_SHORT).show();return false;}});
  w.setWebViewClient(new WebViewClient(){@Override public boolean shouldOverrideUrlLoading(WebView view,WebResourceRequest r){Uri u=r.getUrl();String scheme=u.getScheme()==null?"":u.getScheme().toLowerCase(Locale.ROOT);if(!scheme.equals("http")&&!scheme.equals("https")){try{startActivity(new Intent(Intent.ACTION_VIEW,u));}catch(Exception ignored){}return true;}
   if(r.isForMainFrame()&&confirmRedirect&&!r.hasGesture()){String nh=u.getHost(),oh=host(view.getUrl());if(nh!=null&&oh!=null&&!sameSite(nh,oh)){pendingUrl=u.toString();pendingTab=tabs.indexOf(t);new AlertDialog.Builder(MainActivity.this).setTitle("Pengalihan situs dicegah").setMessage("Halaman mencoba membuka situs lain:\n"+nh+"\n\nIzinkan pengalihan ini?").setNegativeButton("Tetap di sini",(d,x)->{pendingUrl=null;pendingTab=-1;}).setPositiveButton("Izinkan",(d,x)->{if(pendingUrl!=null&&pendingTab>=0&&pendingTab<tabs.size())tabs.get(pendingTab).web.loadUrl(pendingUrl);pendingUrl=null;pendingTab=-1;}).show();return true;}}return false;}
   @Override public WebResourceResponse shouldInterceptRequest(WebView view,WebResourceRequest r){if(blocking&&blockedHost(r.getUrl().getHost())){synchronized(MainActivity.this){blocked++;}return new WebResourceResponse("text/plain","UTF-8",new ByteArrayInputStream(new byte[0]));}return super.shouldInterceptRequest(view,r);}
   @Override public void onPageStarted(WebView v,String url,android.graphics.Bitmap icon){t.url=url;if(current()==t)address.setText(url);drawTabs();}@Override public void onPageFinished(WebView v,String url){t.url=url;if(current()==t)address.setText(url);drawTabs();}});
  w.setDownloadListener((url,ua,cd,mime,len)->{try{DownloadManager.Request r=new DownloadManager.Request(Uri.parse(url));r.setMimeType(mime);r.addRequestHeader("User-Agent",ua);r.setNotificationVisibility(DownloadManager.Request.VISIBILITY_VISIBLE_NOTIFY_COMPLETED);r.setDestinationInExternalPublicDir(Environment.DIRECTORY_DOWNLOADS,"ShieldSurf-"+System.currentTimeMillis());((DownloadManager)getSystemService(DOWNLOAD_SERVICE)).enqueue(r);Toast.makeText(this,"Unduhan dimulai",0).show();}catch(Exception ex){Toast.makeText(this,"Unduhan gagal",0).show();}});}
 private void switchTab(int i){if(i<0||i>=tabs.size())return;if(active>=0&&active<tabs.size())tabs.get(active).web.setVisibility(View.GONE);active=i;Tab t=tabs.get(i);t.web.setVisibility(View.VISIBLE);address.setText(t.web.getUrl()==null?t.url:t.web.getUrl());drawTabs();}
 private void drawTabs(){if(tabsBar==null)return;tabsBar.removeAllViews();for(int i=0;i<tabs.size();i++){final int ix=i;Tab t=tabs.get(i);LinearLayout pill=new LinearLayout(this);pill.setGravity(Gravity.CENTER_VERTICAL);pill.setPadding(dp(8),0,dp(2),0);pill.setBackground(round(i==active?0xff2b484c:panel,12));TextView title=new TextView(this);title.setText(shortTitle(t.title,15));title.setTextColor(i==active?accent:fg);title.setTextSize(12);title.setMaxWidth(dp(125));pill.addView(title);Button close=btn("×",16);pill.addView(close,new LinearLayout.LayoutParams(dp(28),dp(32)));title.setOnClickListener(v->switchTab(ix));pill.setOnClickListener(v->switchTab(ix));close.setOnClickListener(v->closeTab(ix));LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-2,dp(35));lp.setMargins(0,0,dp(5),0);tabsBar.addView(pill,lp);}Button plus=btn("+",21);tabsBar.addView(plus,new LinearLayout.LayoutParams(dp(40),dp(35)));plus.setOnClickListener(v->newTab("https://www.google.com/"));shieldLine.setText((blocking?"🛡 Blokir iklan/pelacak aktif":"Blokir iklan nonaktif")+" • Pop-up diblokir • "+blocked+" permintaan diblokir");}
 private void closeTab(int i){if(tabs.size()==1){tabs.get(0).web.loadUrl("https://www.google.com/");tabs.get(0).title="Beranda";drawTabs();return;}Tab t=tabs.remove(i);webHolder.removeView(t.web);t.web.stopLoading();t.web.loadUrl("about:blank");t.web.destroy();if(i==active)active=-1;else if(i<active)active--;switchTab(active<0?Math.max(0,i-1):active);}
 private Tab current(){return active>=0&&active<tabs.size()?tabs.get(active):null;}
 private void navigate(String raw){String t=raw==null?"":raw.trim();if(t.isEmpty()||current()==null)return;if(t.matches("(?i)^[a-z][a-z0-9+.-]*://.*"))current().web.loadUrl(t);else if(t.contains(" ")||!t.contains("."))current().web.loadUrl("https://www.google.com/search?q="+Uri.encode(t));else current().web.loadUrl("https://"+t);}
 private boolean blockedHost(String host){if(host==null)return false;String h=host.toLowerCase(Locale.ROOT);for(String d:domains)if(h.equals(d)||h.endsWith("."+d))return true;return false;}
 private String host(String url){try{return Uri.parse(url).getHost();}catch(Exception e){return null;}}private boolean sameSite(String a,String b){String x=a.toLowerCase(Locale.ROOT),y=b.toLowerCase(Locale.ROOT);return x.equals(y)||x.endsWith("."+y)||y.endsWith("."+x);}private String shortTitle(String s,int n){if(s==null)return "Tab baru";return s.length()<=n?s:s.substring(0,n-1)+"…";}
 private void bookmark(){Tab t=current();if(t==null||t.web.getUrl()==null)return;SharedPreferences p=getSharedPreferences("bookmarks",0);Set<String>s=new HashSet<>(p.getStringSet("urls",new HashSet<>()));s.add(t.web.getUrl());p.edit().putStringSet("urls",s).apply();Toast.makeText(this,"Bookmark disimpan",0).show();}
 private void showMenu(){String[] a={"Bookmark tersimpan","Perlindungan & privasi","Hapus cookie dan data situs","Beranda"};new AlertDialog.Builder(this).setTitle("ShieldSurf").setItems(a,(d,i)->{if(i==0)showBookmarks();else if(i==1)privacy();else if(i==2)clearData();else if(current()!=null)current().web.loadUrl("https://www.google.com/");}).show();}
 private void showBookmarks(){Set<String>s=getSharedPreferences("bookmarks",0).getStringSet("urls",new HashSet<>());if(s.isEmpty()){Toast.makeText(this,"Belum ada bookmark",0).show();return;}String[] a=s.toArray(new String[0]);new AlertDialog.Builder(this).setTitle("Bookmark").setItems(a,(d,i)->{if(current()!=null)current().web.loadUrl(a[i]);}).setNegativeButton("Tutup",null).show();}
 private void privacy(){String[] a={"Pemblokiran iklan/pelacak: "+(blocking?"AKTIF":"NONAKTIF"),"Pop-up/jendela baru: SELALU DIBLOKIR","Konfirmasi pengalihan otomatis: "+(confirmRedirect?"AKTIF":"NONAKTIF"),"Jumlah permintaan diblokir: "+blocked};new AlertDialog.Builder(this).setTitle("Perlindungan & privasi").setItems(a,(d,i)->{if(i==0){blocking=!blocking;getPreferences(0).edit().putBoolean("blocking",blocking).apply();}else if(i==1){Toast.makeText(this,"Pop-up selalu diblokir demi keamanan",Toast.LENGTH_SHORT).show();return;}else if(i==2){confirmRedirect=!confirmRedirect;getPreferences(0).edit().putBoolean("redirects",confirmRedirect).apply();}else{new AlertDialog.Builder(this).setMessage("Permintaan domain yang diblokir: "+blocked).setPositiveButton("OK",null).show();return;}drawTabs();Toast.makeText(this,"Pengaturan diperbarui",0).show();}).show();}
 private void clearData(){new AlertDialog.Builder(this).setTitle("Hapus data situs?").setMessage("Cache, cookie, dan data situs akan dihapus. Bookmark tetap tersimpan.").setNegativeButton("Batal",null).setPositiveButton("Hapus",(d,w)->{for(Tab t:tabs){t.web.clearCache(true);t.web.clearHistory();t.web.clearFormData();}CookieManager.getInstance().removeAllCookies(v->{CookieManager.getInstance().flush();Toast.makeText(this,"Data situs dibersihkan",0).show();});}).show();}
 @Override public void onBackPressed(){Tab t=current();if(t!=null&&t.web.canGoBack())t.web.goBack();else if(tabs.size()>1)closeTab(active);else super.onBackPressed();}
 @Override protected void onDestroy(){for(Tab t:tabs){try{t.web.stopLoading();t.web.destroy();}catch(Exception ignored){}}tabs.clear();super.onDestroy();}
}
